        Entry("tensor-basis", "tensorBasis", "Ordinary tensor basis", Q("A",V("Word"),Q("B",V("Word"),Equal(TB(V("A"),V("B")),Tensor(WB(V("A")),WB(V("B")))))), "The basis index is Word times Word. There is no factorial normalization.", DescribeRole.Definition),
        Entry("weight-window", "weightWindow", "Exact finite original-weight window", Q("N",V("N"),Equal(Call("weightWindow",V("N")),Call("filter",Call("lambda",V("w"),Le(Call("weight",V("w")),V("N"))),Call("image",Call("lambda",V("l"),Call("ofList",Call("map",V("finVal"),V("l")))),Call("boundedLists",Call("Fin",Add(V("N"),Num(1))),V("N")))))), "boundedLists(Fin(N+1),N) is the finite set of lists of length at most N on the finite alphabet Fin(N+1). Mapping values back to natural indices and filtering by original weight gives exactly the desired words. Every letter weight is positive, including gamma(0)=1.", DescribeRole.Definition),
        Entry("mem-weight-window", "mem_weightWindow", "Exact window membership", Q("N",V("N"),Q("w",V("Word"),Seq(Mem(V("w"),Call("weightWindow",V("N"))),Sp,Iff,Sp,Le(Call("weight",V("w")),V("N"))))), "A word of weight at most N has length at most N and every index at most N. Conversely the weight filter imposes the exact bound.", DescribeRole.Theorem),
        Entry("delta-word", "deltaWord", "Finite transpose on an original basis word", Q("w",V("Word"),Equal(Call("deltaWord",V("w")),Sum(Call("product",Call("weightWindow",Call("weight",V("w"))),Call("weightWindow",Call("weight",V("w")))),"ab",Call("smulQ",Coeff(Call("starWord",Call("fst",V("ab")),Call("snd",V("ab"))),V("w")),TB(Call("fst",V("ab")),Call("snd",V("ab"))))))), "This is tensorBasis.repr.symm applied to the finitely supported function with value [w](A starWord B). Homogeneity proves that nonzero coordinates lie inside the displayed product window; no outside pair is discarded.", DescribeRole.Definition),
        Entry("pairing", "pairing", "Ordinary bilinear word pairing", Q("P",V("H"),Q("Q",V("H"),Equal(Call("pairing",V("P"),V("Q")),Sum(Call("support",V("P")),"w",Multiply(Coeff(V("P"),V("w")),Coeff(V("Q"),V("w"))))))), "Both polynomials have finite support. This is the bilinear extension of the ordinary Kronecker pairing on words, including the empty word.", DescribeRole.Definition),
        Entry("pairing-basis", "pairing_basis", "Pairing with a basis word extracts its coefficient", Q("w",V("Word"),Q("P",V("H"),Equal(Call("pairing",WB(V("w")),V("P")),Coeff(V("P"),V("w"))))), "The polynomial P is arbitrary and the basis word may be empty. Coefficients have the ordinary coefficient-one normalization.", DescribeRole.Theorem),
        Entry("tensor-pairing","tensorPairing","Ordinary bilinear tensor pairing",Q("Q",V("H"),Q("R",V("H"),Q("U",V("H"),Q("V",V("H"),Equal(Call("tensorPairing",V("Q"),V("R"),Tensor(V("U"),V("V"))),Multiply(Call("pairing",V("Q"),V("U")),Call("pairing",V("R"),V("V")))))))),"tensorPairing is bilinear in Q and R and Q-linear in its tensor argument. It is TensorProduct.lift of the product of the ordinary pairing functionals, so the displayed simple-tensor identity specifies the actual algebraic tensor pairing.",DescribeRole.Definition),
        Entry("transpose-property","transposeProperty","Original full transpose characterization",Q("D",V("LinearMapQHTensorHH"),Seq(Call("transposeProperty",V("D")),Sp,Iff,Sp,Q("P",V("H"),Q("Q",V("H"),Q("R",V("H"),Equal(Call("tensorPairing",V("Q"),V("R"),Call("apply",V("D"),V("P"))),Call("pairing",V("P"),Call("star",V("Q"),V("R"))))))))),"LinearMapQHTensorHH denotes Q-linear maps H to H tensor H. Equality is required for every triple of finite rational polynomials, with the ordinary tensor pairing and the original primitive-unshuffle product.",DescribeRole.Definition),
        Entry("delta", "delta", "The unique original ordinary ari coproduct", And(Call("transposeProperty",V("delta")),Q("D",V("LinearMapQHTensorHH"),Imp(Call("transposeProperty",V("D")),Equal(V("D"),V("delta"))))), "delta is chosen from a proved unique-existence theorem for transposeProperty. Existence is constructed by the linear extension of deltaWord. Uniqueness follows by the ordinary tensor basis coefficients. This identifies the finite construction with Definition 1.20; it introduces no assumed comparison map or completed tensor product.", DescribeRole.Definition),
        Entry("delta-transpose","delta_transpose","The full original ordinary transpose identity",Q("P",V("H"),Q("Q",V("H"),Q("R",V("H"),Equal(Call("tensorPairing",V("Q"),V("R"),Call("delta",V("P"))),Call("pairing",V("P"),Call("star",V("Q"),V("R"))))))),"All three polynomials are arbitrary, including zero and the unit. This is Definition 1.20 with the ordinary pairing of words and the actual finite original product.",DescribeRole.Theorem),
        Entry("delta-coefficient", "delta_coefficient", "Full ordinary transpose identity", Q("P",V("H"),Q("A",V("Word"),Q("B",V("Word"),Equal(TC(Call("delta",V("P")),V("A"),V("B")),Call("pairing",V("P"),Call("star",WB(V("A")),WB(V("B")))))))), "The identity holds for arbitrary rational input and all basis pairs. Bilinearity extends the identity to arbitrary polynomials in each paired factor.", DescribeRole.Theorem),
        Entry("delta-basis-coefficient", "delta_basis_coefficient", "All basis coefficients including outside the window", Q("w",V("Word"),Q("A",V("Word"),Q("B",V("Word"),Equal(TC(Call("delta",WB(V("w"))),V("A"),V("B")),Coeff(Call("starWord",V("A"),V("B")),V("w")))))), "Either A or B may be empty, and neither is assumed to belong to the defining finite window. Outside-window coefficients vanish by original-weight homogeneity.", DescribeRole.Theorem),
        Entry("filtration", "filtration", "Original rational level filtration", Ns(new[]{"k","r"},Equal(Call("filtration",V("k"),V("r")),Call("spanQ",Call("image",V("wordBasis"),Call("set",V("w"),Le(Call("level",V("k"),V("w")),V("r"))))))), "The set variable w ranges over all original words. This is the rational span of the words with at most r letters different from k, with no restriction on their weight or length.", DescribeRole.Definition),
        Entry("right-filtration-image", "rightFiltrationImage", "The actual tensor-submodule image", Ns(new[]{"k","r"},Equal(Call("rightFiltrationImage",V("k"),V("r")),Call("range",Call("tensorMap",V("idH"),Call("subtype",Call("filtration",V("k"),V("r"))))))), "idH is the identity Q-linear map on H, and subtype is the natural inclusion of filtration(k,r) into H. The domain of the tensor map is H tensor filtration(k,r), and its range is a submodule of H tensor H.", DescribeRole.Definition),
        Entry("claim", "claim", "Complete original Conjecture 4.29", Seq(V("claim"),Sp,Iff,Sp,Ns(new[]{"k","r"},Q("P",V("H"),Imp(Mem(V("P"),Call("filtration",V("k"),V("r"))),Mem(Call("delta",V("P")),Call("rightFiltrationImage",V("k"),V("r"))))))), "For every natural k and r and every finite rational word polynomial P in the original level span, the original ordinary ari coproduct lies in the image of H tensor that same right-factor span. The case k=0, the unit, arbitrary lengths, rational coefficients and cancellation are all included.", DescribeRole.Definition),
        Entry("result", "result", "The full right-factor filtration assertion", Ns(new[]{"k","r"},Q("P",V("H"),Imp(Mem(V("P"),Call("filtration",V("k"),V("r"))),Mem(Call("delta",V("P")),Call("rightFiltrationImage",V("k"),V("r")))))), "The product support bound forces every nonzero transpose coefficient at (A,B) to have level(k,B) at most level(k,w). Each allowed tensor basis vector is the image of wordBasis(A) tensor an actual element of the filtration submodule. Basis spans and Q-linearity give the assertion for every P in the filtration.", DescribeRole.Theorem))));
    private static DocumentBlock Entry(string id, string declaration, string title, Formula formula, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(id), DeclarationHandle.Create(Module + "." + declaration), H(title),
            StatementSource.FromAuthor(Disp(formula)), AssessedProvenance.FromRepo(Source), Blocks(Paragraph(Text(prose))), role);
    private static Formula V(string s) => F.Id(s);
    private static Formula Q(string x, Formula t, Formula b) => Seq(Forall,Sp,V(x),Colon,t,Comma,b);
    private static Formula Ns(string[] xs, Formula b) { for (var i=xs.Length-1;i>=0;i--) b=Q(xs[i],V("N"),b); return b; }
    private static Formula Imp(Formula a, Formula b) => Seq(Open,a,Close,Sp,Implies,Sp,b);
    private static Formula And(Formula a, Formula b) => Seq(Open,a,Close,Sp,Land,Sp,Open,b,Close);
    private static Formula Mem(Formula a, Formula b) => Seq(a,Sp,InMacro,Sp,b);
    private static Formula Le(Formula a, Formula b) => Seq(a,Sp,Leq,Sp,b);
    private static Formula Coeff(Formula p, Formula w) => Call("coeff",p,w);
    private static Formula Tensor(Formula a, Formula b) => Call("tmulQ",a,b);
    private static Formula WB(Formula a) => Call("wordBasis",a);
    private static Formula TB(Formula a, Formula b) => Call("tensorBasis",Call("pair",a,b));
    private static Formula TC(Formula p, Formula a, Formula b) => Call("apply",Call("tensorCoordinates",p),Call("pair",a,b));
    private static Formula Sum(Formula set, string x, Formula body) => Call("sum",set,Call("lambda",V(x),body));
